import{_ as t,C as n,o,c as l,j as i,E as e,a as s,a3 as d}from"./chunks/framework.C6R8kWFE.js";const b=JSON.parse(`{"title":"3-hafta","description":"","frontmatter":{"title":"3-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/9-sinf/"},"n":3,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":7,"title":"Axure RP: Dinamik panellar va interaktiv bog'lanishlar (Interactions)","lead":"Statik chizmalardan chertiladigan (clickable) prototiplarga o'tish, Dinamik panellar va sahifalararo navigatsiya sirlari.","link":"/9-sinf/hafta-03/dars-1","slide":"/slaydlar/9-sinf/hafta-03/dars-1.html","test":"/slaydlar/9-sinf/hafta-03/dars-1-test.html"},{"g":8,"title":"Foydalanuvchi formalari, kiritish maydonlari va xatoliklar dizayni (Form Wireframing)","lead":"Kiritish elementlari (Input, Dropdown, Radio, Checkbox), maydon holatlari, inline validation va xatoliklardan qutqaruvchi qulay interfeyslar.","link":"/9-sinf/hafta-03/dars-2","slide":"/slaydlar/9-sinf/hafta-03/dars-2.html","test":"/slaydlar/9-sinf/hafta-03/dars-2-test.html"},{"g":9,"title":"Wireframe loyihasini yakunlash, annotatsiyalar va Figmaga eksport","lead":"Izohli simli ramkalar (Annotated wireframes), PNG/SVG/PDF eksport va Figmada UI dizayn uchun referens qatlamini sozlash.","link":"/9-sinf/hafta-03/dars-3","slide":"/slaydlar/9-sinf/hafta-03/dars-3.html","test":"/slaydlar/9-sinf/hafta-03/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"9-sinf/hafta-03/index.md","filePath":"9-sinf/hafta-03/index.md"}`),h={name:"9-sinf/hafta-03/index.md"},m={class:"blk"},c={id:"uyga-vazifa",tabindex:"-1"};function k(g,a,u,f,y,p){const r=n("Icon");return o(),l("div",null,[i("div",m,[i("h2",c,[e(r,{name:"house"}),a[0]||(a[0]=s(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Natijalarni daftarda yoki dizayn dasturida (Axure RP, Balsamiq, Figma) alohida papkada saqlang. Topshirish: keyingi dars boshida mentorga ko&#39;rsating.</p><h3 id="_7-dars-uchun-axure-rp-dinamik-panellar-va-interaksiyalar" tabindex="-1">7-dars uchun (Axure RP: Dinamik panellar va interaksiyalar) <a class="header-anchor" href="#_7-dars-uchun-axure-rp-dinamik-panellar-va-interaksiyalar" aria-label="Permalink to &quot;7-dars uchun (Axure RP: Dinamik panellar va interaksiyalar)&quot;">​</a></h3><p><strong>1-topshiriq: «Chertiladigan kitob kartasi va tablar»</strong> (20–25 daqiqa)</p><ol><li>Axure RP (yoki bepul interaktiv analog)da 2 ta sahifa yarating: <code>Home_books</code> va <code>Book_details</code>.</li><li><code>Home_books</code>dagi kitob kartasiga <code>OnClick</code> hodisasi orqali <code>Open Link</code> → <code>Book_details</code> amalini biriktiring.</li><li><code>Book_details</code> sahifasida Dynamic Panel yarating va 2 ta State hosil qiling («Annotatsiya» va «Kitob haqida fikrlar»).</li><li>Yuqoridagi 2 ta tugmaga <code>Set Panel State</code> amalini bog&#39;lab, tablarni bir-biriga almashtiruvchi interaktivlikni sozlang.</li><li>Loyihani Preview rejimida brauzerda tekshiring.</li></ol><p><strong>Kutiladigan natija:</strong> sahifalararo o&#39;tuvchi va bitta ekranda tablarni yangilaydigan ishchi interaktiv prototip. <strong>Nimani topshirasiz:</strong> prototipning qisqa video-yozuvi (screen record) yoki dastur fayli (<code>.rp</code>).</p><h3 id="_8-dars-uchun-formalar-kiritish-maydonlari-va-xatoliklar-dizayni" tabindex="-1">8-dars uchun (Formalar, kiritish maydonlari va xatoliklar dizayni) <a class="header-anchor" href="#_8-dars-uchun-formalar-kiritish-maydonlari-va-xatoliklar-dizayni" aria-label="Permalink to &quot;8-dars uchun (Formalar, kiritish maydonlari va xatoliklar dizayni)&quot;">​</a></h3><p><strong>2-topshiriq: «Ro&#39;yxatdan o&#39;tish formasi va Error State»</strong> (20–30 daqiqa)</p><ol><li>«E-kutubxona» uchun ro&#39;yxatdan o&#39;tish formasining to&#39;liq wireframe&#39;ini chizing (Label, Input, Placeholder, Helper text va Submit tugmasi).</li><li>Quyidagi kiritish turlarini to&#39;g&#39;ri ishlating: <ul><li>To&#39;liq ism (<code>Text Field</code>);</li><li>Parol (<code>Password Field</code> + ko&#39;zcha);</li><li>Sevimli janrlar (<code>Checkbox</code> — kamida 3 ta variant);</li><li>Bildirishnomalarni olish usuli (<code>Radio Button</code> — Email / SMS).</li></ul></li><li>Ushbu formaning «Xatolik holati» (Error state)ni alohida chizing: noto&#39;g&#39;ri email kiritilganda maydon qanday ko&#39;rinishi va tagidagi mikro-matn qanday yozilishini ko&#39;rsating.</li></ol><p><strong>Kutiladigan natija:</strong> barcha element turlari to&#39;g&#39;ri tanlangan toza forma wireframe&#39;i va uning xatolik holati. <strong>Nimani topshirasiz:</strong> 2 ta ekran skrinshoti (boshlang&#39;ich holat va xatolik holati).</p><h3 id="_9-dars-uchun-wireframe-loyihasini-yakunlash-va-figmaga-eksport" tabindex="-1">9-dars uchun (Wireframe loyihasini yakunlash va Figmaga eksport) <a class="header-anchor" href="#_9-dars-uchun-wireframe-loyihasini-yakunlash-va-figmaga-eksport" aria-label="Permalink to &quot;9-dars uchun (Wireframe loyihasini yakunlash va Figmaga eksport)&quot;">​</a></h3><p><strong>3-topshiriq: «E-kutubxona to&#39;liq karkasi va Figma referens qatlami»</strong> (25–30 daqiqa)</p><ol><li>Hafta davomida yaratilgan barcha ekranlarni (<code>Home_books</code>, <code>Book_details</code>, <code>Register_modal</code>) tekshiring va kamida 3 ta blok ustiga raqamli annotatsiya (texnik izoh) yozing.</li><li>Loyihani toza PNG formatida eksport qiling.</li><li>Figma dasturida <code>Desktop 1440</code> o&#39;lchamli Frame ochib, ushbu PNG rasmni joylang, Opacity darajasini <code>40%</code> ga tushiring va qatlamni qulflang (<code>Lock</code>).</li><li>Qulflangan karkas ustidan bitta kitob kartasining birinchi rangli UI variantini (fon, rasm o&#39;rni, chiroyli tugma) chizib ko&#39;ring.</li></ol><p><strong>Kutiladigan natija:</strong> dasturchilar uchun annotatsiyalangan wireframe va Figmada UI dizayn uchun tayyorlangan referens qatlam. <strong>Nimani topshirasiz:</strong> Figmadagi loyiha havolasi (link) yoki eksport qilingan skrinshot.</p>',13))])])}const q=t(h,[["render",k]]);export{b as __pageData,q as default};
